30	template<typename T, typename Operator>
31	__device__ __forceinline__ T warp_reduce(T val, Operator op) {
32	    // Get the thread's position within its group of 4
33	    const int lane_id = threadIdx.x % 32;  // Lane ID within warp
34	    const int group_pos = lane_id % 4;     // Position within group of 4
35	    
36	    // Only reduce with threads that have the same position in their group of 4
37	    // Using butterfly pattern with xor
38	    for (int mask = 16; mask > 0; mask >>= 1) {
39	        T other = __shfl_xor_sync(0xffffffff, val, mask);
40	        // Only combine if the other thread has the same group_pos
41	        if ((lane_id ^ mask) < 32 && ((lane_id ^ mask) % 4 == group_pos)) {
42	            val = op(val, other);
43	        }
44	    }
45	    return val;
46	}
