117	        const int num_params_2   = size<1>(src) == 4 ? num_params / 2 : num_params; // TODO: change name? seems hard code? 
118	        const int channel_stride = size<0>(src);
119	
120	        // Declare per-channel tensors
121	        using TensorChannel = decltype(make_fragment_like<float>(scales_k(_, 0)));
122	        TensorChannel channel_max, channel_min, channel_range, channel_scales_inv, channel_zeros;
123	
124	        CUTE_UNROLL
