    using TensorChannel = decltype(make_fragment_like<float>(scales_k_g));
    TensorChannel channel_max, channel_min, channel_range, channel_scales_inv, channel_zeros;

    CUTE_UNROLL
    for (int k = 0; k < size<1>(src); ++k) {
